head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[multiselect > P > invalidMessageFunc]<br/>입력값에 대한 유효성 체크를 통과하지 못한 경우 메시지를 동적으로 생성하기 위한 사용자 정의 함수를 설정합니다.",
    "validation" : [
        "메시지를 생성할 사용자 정의 함수를 설정합니다.",
        "사용자 정의 함수의 반환값이 새로운 메시지로 적용됩니다.",
        "displaymessage=true 이고 validate() 메소드 실행결과가 실패일때 동작합니다.",
        "displaymessage=true 이고 validateObject() 메소드 실행결과가 실패일때 동작합니다.",
        "사용자 정의 함수에서 반환된 값은 alert() 메소드로 표시됩니다.",
        "사용자 정의 함수에서 this 를 통해 입력값 유효성 체크가 실행된 컴포넌트의 렌더링 ID 를 갖는 callerId 속성을 사용할 수 있습니다.",
        "사용자 정의 함수에서 this 를 통해 입력값 유효성 체크가 실행된 컴포넌트를 반환하는 getCaller() 메소드를 사용할 수 있습니다.",
        "사용자 정의 함수에서 this 를 통해 입력값 유효성 체크를 통과하지 못한 항목을 문자열로 반환하는 getType() 메소드 ('mandatory' 값을 가짐) 를 사용할 수 있습니다.",
        "사용자 정의 함수에서 this 를 통해 입력값 유효성 체크를 통과하지 못한 항목의 속성값을 반환하는 getValue() 메소드를 사용할 수 있습니다.",        
    ]
}



scwin.wf_sample_onwframeload = function () {
    let wf_body_left = wf_sample.getObj("wf_body_left");
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성 (createBasicMultiSelect 로 동적 생성, invalidMessageFunc 속성 적용)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // gdl_multiselect 재생성 (idempotent: 기존 dataList 제거 후 재생성)
    $c.gcm.createDataListMultiSelect();

    // 조건 설정
    let properties = {
        displaymessage: true,
        mandatory: true,
        // invalidMessage: wf_sample.getObj("con_invalidMessage").getValue(),
        invalidMessageFunc: wf_sample.getObj("con_invalidMessageFunc").getText(),
    };

    let cList = $c.gcm.createCList(properties);

    $c.gcm.createBasicMultiSelect(cList);
}
